create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,matricula text unique not null,nome text not null default 'Administrador',perfil text not null default 'admin',created_at timestamptz default now());
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,date date default current_date,type text not null check(type in ('revenue','expense')),description text default '',category text default '',value numeric(14,2) default 0,created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,category text default '',unit text default 'un.',qty numeric(14,2) default 0,min numeric(14,2) default 0,ideal numeric(14,2) default 0,cost numeric(14,2) default 0,price numeric(14,2) default 0,created_at timestamptz default now());
create table if not exists public.investments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,date date default current_date,description text default '',category text default '',value numeric(14,2) default 0,created_at timestamptz default now());
create table if not exists public.clients(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,phone text,doc text,email text,created_at timestamptz default now());
create table if not exists public.vehicles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,client_id uuid references public.clients(id) on delete set null,brand text,model text,year int,color text,type text,created_at timestamptz default now());
create table if not exists public.services(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,category text,price numeric(14,2) default 0,duration int default 0,status text default 'Ativo',created_at timestamptz default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,code text,date date default current_date,client_id uuid references public.clients(id) on delete set null,vehicle_id uuid references public.vehicles(id) on delete set null,service_id uuid references public.services(id) on delete set null,total numeric(14,2) default 0,status text default 'Agendada',created_at timestamptz default now());
create table if not exists public.employees(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,role text,department text,hour numeric(14,2) default 0,status text default 'Ativo',created_at timestamptz default now());
create table if not exists public.hours(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,employee_id uuid references public.employees(id) on delete set null,date date default current_date,start_time time,end_time time,break_minutes int default 0,created_at timestamptz default now());
create table if not exists public.machines(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,model text,department text,value numeric(14,2) default 0,status text default 'Operando',created_at timestamptz default now());
create table if not exists public.purchases(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id uuid references public.products(id) on delete set null,date date default current_date,qty numeric(14,2) default 0,unit numeric(14,2) default 0,total numeric(14,2) default 0,status text default 'Solicitada',created_at timestamptz default now());
create table if not exists public.goals(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,period text,description text,target numeric(14,2) default 0,actual numeric(14,2) default 0,created_at timestamptz default now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['transactions','products','investments','clients','vehicles','services','orders','employees','hours','machines','purchases','goals'] LOOP EXECUTE format('alter table public.%I enable row level security',t); EXECUTE format('drop policy if exists own_access on public.%I',t); EXECUTE format('create policy own_access on public.%I for all using (user_id=auth.uid()) with check (user_id=auth.uid())',t); END LOOP; END $$;
